import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type BlurListRevealProps = Record<string, any>;

const BlurListReveal: React.FC<BlurListRevealProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 8,
  accentColor = "#D90000",
  textColor = "#ffffff",
  listItems = ["WHAT IS MARKETING?", "HOW TO SELL", "CLOSING THE DEAL"],
  blurIntensity = 20,
  stepDelay = 1.5,
  lineHeight = 0.9,
}) => {
  useFontLoader(["Oswald"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const containerStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
    width: "100%",
    height: "100%",
    gap: width * 0.05,
    padding: `0 ${width * 0.05}px`,
  };

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div style={containerStyle}>
        {listItems.map((item, index) => {
          // Stagger logic
          // Index 0 starts clear immediately (or fades in quickly)
          // Index 1 unblurs after stepDelay
          // Index 2 unblurs after stepDelay * 2
          
          const activationStartFrame = index === 0 ? 0 : index * (stepDelay * fps);
          
          // Blur Animation
          // If index 0, it starts unblurred. If index > 0, it transitions from blur to clear.
          const blurVal = interpolate(
            frame,
            [activationStartFrame, activationStartFrame + fps],
            [index === 0 ? 0 : blurIntensity, 0],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.out(Easing.cubic),
            }
          );

          // Opacity / Fade In for the whole block initially
          const initialEntrance = spring({
            frame: frame - index * 5, // slight stagger for initial appearance
            fps,
            config: { damping: 20 },
          });

          // Text Color / Opacity during blur
          // When blurred, text is slightly transparent to simulate the reference look
          const textOpacity = interpolate(
             frame,
             [activationStartFrame, activationStartFrame + fps],
             [0.4, 1],
             { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Bar Progress Animation
          // Active step bar fills up or turns white
          const barColorInterpolation = interpolate(
            frame,
            [activationStartFrame, activationStartFrame + fps],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Colors need to be handled carefully with interpolation if using pure hex
          // Simple approach: switch class or opacity of overlay
          // We will use an overlay for the "active" white bar
          
          const scale = interpolate(
             frame, 
             [activationStartFrame, activationStartFrame + fps],
             [0.95, 1],
             { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.ease)}
          )

          return (
            <div
              key={index}
              style={{
                flex: 1,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "flex-end", // Align towards bottom like reference
                height: height * 0.6, // constrain height
                opacity: initialEntrance,
                transform: `translateY(${interpolate(initialEntrance, [0, 1], [50, 0])}px)`,
              }}
            >
              {/* Text Area */}
              <div
                style={{
                  flex: 1,
                  display: "flex",
                  alignItems: "flex-end", // Text sits at bottom of its area
                  marginBottom: 30,
                  width: "100%",
                }}
              >
                <h1
                  style={{
                    fontFamily: "Oswald, sans-serif",
                    color: textColor,
                    fontSize: 80, // Responsive scaling would be better but fixed is okay for 1080p baseline
                    lineHeight: lineHeight,
                    textAlign: "center",
                    textTransform: "uppercase",
                    width: "100%",
                    margin: 0,
                    filter: `blur(${blurVal}px)`,
                    opacity: textOpacity,
                    transform: `scale(${scale})`,
                    transformOrigin: "bottom center",
                    willChange: "filter, opacity, transform",
                  }}
                >
                  {item}
                </h1>
              </div>

              {/* Progress Bar Container */}
              <div
                style={{
                  width: "100%",
                  position: "relative",
                  height: 20,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                {/* Background Gray Bar */}
                <div
                  style={{
                    position: "absolute",
                    left: 0,
                    right: 0,
                    height: 12, // Thickness of bar
                    backgroundColor: "rgba(255,255,255,0.2)",
                    borderRadius: 6,
                  }}
                />

                {/* Active White Bar (reveals smoothly) */}
                <div
                  style={{
                    position: "absolute",
                    left: 0,
                    right: 0,
                    height: 12,
                    backgroundColor: "#ffffff",
                    borderRadius: 6,
                    opacity: barColorInterpolation,
                  }}
                />

                {/* Red Badge */}
                <div
                  style={{
                    position: "absolute",
                    width: 60,
                    height: 60,
                    borderRadius: "50%",
                    backgroundColor: accentColor,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    boxShadow: "0 4px 10px rgba(0,0,0,0.5)",
                    zIndex: 10,
                  }}
                >
                  <span
                    style={{
                      fontFamily: "Oswald, sans-serif",
                      color: "#ffffff",
                      fontSize: 32,
                      fontWeight: 700,
                    }}
                  >
                    {index}
                  </span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default BlurListReveal;